package com.lmspilot.assessment.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="exam_sessions",uniqueConstraints=@UniqueConstraint(name="uq_exam_submit_key",columnNames="submit_idempotency_key")) public class ExamSessionEntity { @Id public UUID id=UUID.randomUUID(); @Column(nullable=false) public UUID examId; @Column(nullable=false) public int examVersion=1; @Column(nullable=false) public UUID userId; public UUID enrollmentId; public UUID courseId; public UUID lessonId; @Column(nullable=false) public int attemptNo=1; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) public ExamSessionStatus status=ExamSessionStatus.IN_PROGRESS; @Column(nullable=false) public Instant startedAt=Instant.now(); @Column(nullable=false) public Instant expiresAt=Instant.now(); @Column(nullable=false) public Instant graceUntil=Instant.now(); @Column(nullable=false) public Instant lastHeartbeatAt=Instant.now(); @Column(nullable=false) public int suspiciousEventCount; public Instant submittedAt; @Column(nullable=false,columnDefinition="text") public String answersJson="{}"; @Column(length=160) public String submitIdempotencyKey; @Column(nullable=false) public Instant updatedAt=Instant.now(); @Version public long rowVersion; public ExamSessionEntity(){} }
